class Dhikr {
  final String id, cat, text, virtue, source;
  final int repeat;
  const Dhikr(this.id, this.cat, this.text, this.repeat, this.virtue, this.source);
}

Dhikr _d(String cat, int i, String text, int repeat, String virtue, String source) =>
    Dhikr('$cat-$i', cat, text, repeat, virtue, source);

